var HEROES = [{"id":"OREH-FR-2018-0323","country":"FR","date":"2018-03-23","cat":"duty","outcome":"died","ko":{"name":"아르노 벨트람","place":"프랑스 트레브","headline":"인질 대신 남은 헌병 장교","story":"슈퍼마켓 인질극 현장에서 헌병 장교 아르노 벨트람이 인질 대신 자신이 남겠다고 나섰고, 범인의 공격으로 숨졌습니다.","verified":"언론 보도 · 국가 추모식"},"en":{"name":"Arnaud Beltrame","place":"Trèbes, France","headline":"The officer who took a hostage's place","story":"During a hostage-taking at a supermarket, gendarmerie officer Arnaud Beltrame offered himself in exchange for a hostage. He was killed by the attacker.","verified":"News reports · National tribute"},"zh":{"name":"阿尔诺·贝尔特拉姆","place":"法国特雷布","headline":"替换人质的宪兵军官","story":"在一家超市的劫持人质事件中，宪兵军官阿尔诺·贝尔特拉姆主动提出以自己交换人质，最终遇害。","verified":"新闻报道 · 国家追悼仪式"},"ja":{"name":"アルノー・ベルトラム","place":"フランス・トレーブ","headline":"人質の身代わりになった憲兵将校","story":"スーパーマーケットの人質事件で、憲兵隊将校のアルノー・ベルトラム氏が人質の身代わりを申し出て、犯人の襲撃により亡くなりました。","verified":"報道 · 国家追悼式"}},{"id":"OREH-US-2017-0526","country":"US","date":"2017-05-26","cat":"crime","outcome":"died","ko":{"name":"탈리에신 남카이-메체 · 리키 베스트 · 마이카 플레처","place":"오리건주 포틀랜드","headline":"혐오 폭력을 막아선 세 시민","story":"경전철 안에서 10대 소녀 두 명에게 혐오 발언을 퍼붓던 남성을 막아서다 흉기에 찔려, 두 명이 숨지고 한 명이 크게 다쳤습니다.","verified":"언론 보도"},"en":{"name":"Taliesin Namkai-Meche, Ricky Best, Micah Fletcher","place":"Portland, Oregon","headline":"Three passengers who stood up to hate","story":"On a light-rail train, they stepped in to stop a man hurling hateful abuse at two teenage girls. He stabbed them; two died and one was seriously injured.","verified":"News reports"},"zh":{"name":"Taliesin Namkai-Meche, Ricky Best, Micah Fletcher","place":"俄勒冈州波特兰","headline":"挺身制止仇恨暴力的三位市民","story":"在轻轨列车上，他们挺身制止一名对两名少女发表仇恨言论的男子，遭其持刀刺伤，两人死亡、一人重伤。","verified":"新闻报道"},"ja":{"name":"タリエシン・ナムカイ＝メチェ、リッキー・ベスト、マイカ・フレッチャー","place":"オレゴン州ポートランド","headline":"憎悪の暴力に立ち向かった3人の市民","story":"ライトレールの車内で、10代の少女2人に憎悪に満ちた暴言を浴びせる男を止めに入り、刃物で刺されて2人が亡くなり、1人が重傷を負いました。","verified":"報道"}},{"id":"OREH-KR-2016-0909","country":"KR","date":"2016-09-09","cat":"rescue","outcome":"died","ko":{"name":"안치범","place":"서울 마포구","headline":"초인종을 눌러 이웃을 깨운 청년","story":"새벽 원룸 건물에 불이 나자 밖으로 대피한 뒤 다시 들어가 집집마다 초인종을 눌러 이웃을 깨웠습니다. 연기를 들이마셔 치료를 받다 숨졌고, 의사자로 인정되었습니다.","verified":"언론 보도 · 의사자 인정"},"en":{"name":"Ahn Chi-beom","place":"Mapo-gu, Seoul","headline":"The young man who rang every doorbell","story":"When a fire broke out in his building before dawn, he got out, then went back in and rang doorbells to wake his neighbors. He died in hospital from smoke inhalation and was officially recognized as an uisaja, a person who died saving others.","verified":"News reports · Recognized as uisaja"},"zh":{"name":"Ahn Chi-beom","place":"首尔麻浦区","headline":"挨家按门铃叫醒邻居的青年","story":"凌晨公寓楼起火，他逃出后又返回楼内，挨家挨户按门铃叫醒邻居。他因吸入浓烟，在治疗中去世，后被认定为义死者。","verified":"新闻报道 · 被认定为义死者"},"ja":{"name":"アン・チボム","place":"ソウル・麻浦区","headline":"呼び鈴を鳴らして隣人を起こした青年","story":"未明にワンルームの建物で火災が起きると、いったん避難した後に再び中へ戻り、一軒ずつ呼び鈴を押して隣人を起こしました。煙を吸って治療中に亡くなり、義死者に認定されました。","verified":"報道 · 義死者認定"}},{"id":"OREH-CN-2012-0508","country":"CN","date":"2012-05-08","cat":"accident","outcome":"injured","ko":{"name":"장리리","place":"헤이룽장성 자무쓰","headline":"학생들을 밀쳐 낸 선생님","story":"하교하던 학생들에게 버스가 돌진하자 교사 장리리가 학생들을 밀쳐 냈고, 자신은 버스에 깔려 두 다리를 잃었습니다.","verified":"언론 보도"},"en":{"name":"Zhang Lili","place":"Jiamusi, Heilongjiang","headline":"The teacher who pushed her students to safety","story":"When a bus lurched toward students leaving school, teacher Zhang Lili pushed them out of the way. She was run over and lost both legs.","verified":"News reports"},"zh":{"name":"张丽莉","place":"黑龙江省佳木斯","headline":"推开学生的老师","story":"一辆失控的客车冲向放学的学生，教师张丽莉推开学生，自己却被卷入车下，失去了双腿。","verified":"新闻报道"},"ja":{"name":"張麗莉","place":"黒竜江省・佳木斯","headline":"生徒を突き飛ばして守った先生","story":"下校中の生徒に向かってバスが突っ込んできた際、教師の張麗莉さんは生徒を突き飛ばして助け、自らはバスの下敷きになって両脚を失いました。","verified":"報道"}},{"id":"OREH-JP-2001-0126","country":"JP","date":"2001-01-26","cat":"rail","outcome":"died","ko":{"name":"이수현 · 세키네 시로","place":"도쿄 JR 신오쿠보역","headline":"선로에 뛰어든 두 사람","story":"선로에 떨어진 남성을 구하려고 한국인 유학생 이수현과 일본인 사진가 세키네 시로가 함께 뛰어내렸다가, 들어오던 열차에 목숨을 잃었습니다.","verified":"언론 보도"},"en":{"name":"Lee Soo-hyun & Shiro Sekine","place":"Shin-Okubo Station, Tokyo","headline":"Two men who jumped onto the tracks","story":"When a man fell onto the tracks, Korean student Lee Soo-hyun and Japanese photographer Shiro Sekine jumped down to save him. Both were killed by an incoming train.","verified":"News reports"},"zh":{"name":"李秀贤 · 关根史郎","place":"东京JR新大久保站","headline":"跳下轨道的两个人","story":"一名男子跌落轨道，韩国留学生李秀贤与日本摄影师关根史郎一同跳下施救，不幸被驶入的列车夺去生命。","verified":"新闻报道"},"ja":{"name":"李秀賢 · 関根史郎","place":"東京・JR新大久保駅","headline":"線路に飛び降りた二人","story":"線路に転落した男性を助けようと、韓国人留学生の李秀賢さんと日本人カメラマンの関根史郎さんが線路に飛び降り、進入してきた電車にはねられて亡くなりました。","verified":"報道"}},{"id":"OREH-TW-1928-0514","country":"TW","date":"1928-05-14","cat":"independence","outcome":"died","ko":{"name":"조명하","place":"대만 타이중","headline":"타이중 의거의 조명하 의사","story":"1928년 5월 14일 대만 타이중에서 일본 육군 대장이자 일왕의 장인인 구니노미야를 향해 독검을 던졌습니다. 현장에서 붙잡혀 그해 10월 10일 타이베이에서 순국했으며, 안중근·이봉창·윤봉길 의사와 함께 대한독립 4대 의사로 기려집니다.","verified":"국가보훈부 공훈록 · 건국훈장 독립장(1963)"},"en":{"name":"Cho Myung-ha","place":"Taichung, Taiwan","headline":"The Korean patriot of the 1928 Taichung attack","story":"On 14 May 1928 in Taichung, he threw a poisoned dagger at Prince Kuni, a Japanese army general and the father-in-law of Emperor Hirohito. Arrested on the spot, he was executed in Taipei on 10 October 1928. Korea honors him as one of the four great patriots of its independence movement, alongside Ahn Jung-geun, Lee Bong-chang and Yun Bong-gil.","verified":"Korean government merit record · Order of Merit for National Foundation, Independence Medal (1963)"},"zh":{"name":"赵明河","place":"台湾台中","headline":"台中义举的赵明河义士","story":"1928年5月14日，他在台湾台中向日本陆军大将、裕仁天皇的岳父久迩宫投掷毒刃，当场被捕，同年10月10日在台北就义。在韩国，他与安重根、李奉昌、尹奉吉并称为“大韩独立四大义士”。","verified":"韩国国家报勋部功勋录 · 建国勋章独立章（1963）"},"ja":{"name":"趙明河","place":"台湾・台中","headline":"1928年台中事件の独立運動家","story":"1928年5月14日、台湾・台中で、日本陸軍大将で昭和天皇の義父にあたる久邇宮邦彦王に向けて毒を塗った短刀を投げました。その場で捕らえられ、同年10月10日に台北で処刑されました。韓国では安重根・李奉昌・尹奉吉と並ぶ「大韓独立四大義士」として称えられています。","verified":"韓国国家報勲部 功勲録 · 建国勲章独立章（1963）"}}];
