function t(k, vars){
  var d = I18N[lang] || {}; var s = d[k];
  if (s == null) s = I18N.ko[k]; if (s == null) s = k;
  if (vars) s = s.replace(/\{(\w+)\}/g, function(m, p){ return vars[p] != null ? String(vars[p]) : m; });
  return s;
}
